input.code:
const dsl = `workspace "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {
    scope "SoftwareSystem"

    model {

        customer = person "Customer" "Uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {
            documentation "overview" "The Parcel Tracker is a parcel delivery tracking platform owned and operated by our company. Customers look up the status of their parcels through a web portal, and a dispatch service assigns parcels to couriers. Both application parts embed a shared pricing rules library that computes delivery prices from weight and zone. The platform stores shipments and dispatch records in its own database, and sends customer notification emails through an external email delivery provider."
            decisions {
                decision "1" "Shared pricing rules library" "The web portal and the dispatch service both embed a shared pricing rules library that computes delivery prices from weight and zone, instead of each part implementing its own pricing logic."
            }
            webPortal = container "Web Portal" "Where customers look up the status of their shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Database" "Stores shipment and dispatch records." "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Sends customer notification emails on behalf of the Parcel Tracker. Operated by a different organization." "External"

        customer -> webPortal "looks up the status of their parcels" "HTTPS/JSON"
        webPortal -> database "reads shipment records" "SQL"
        dispatchService -> database "writes dispatch records" "SQL"
        dispatchService -> emailProvider "sends customer notification emails" "SMTP"
    }

    views {
        systemContext parcelTracker "systemContext" "System Context" "System context diagram for the Parcel Tracker." {
            ADD customer
            ADD emailProvider
            autoLayout
        }
        container parcelTracker "containers" "Containers" "Container diagram for the Parcel Tracker." {
            ADD customer
            ADD emailProvider
            autoLayout
        }
    }
}`;
const [validate, inspect] = await Promise.all([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
return { validate, inspect };

